  "command": "cd /tmp && timeout 30 curl -sS -L "https://www.wuxi.gov.cn/gjj/zfxxgk/xxgkml/fgwjjjd/index.shtml" 2>/dev/null | python3 -c "
import sys,re,html
t=sys.stdin.read()
for m in re.finditer(r'<a[^>]+href=\"([^\"]+)\"[^>]*>(.*?)</a>',t,flags=re.S):
    href,txt=m.group(1),html.unescape(re.sub('<[^>]+>','',m.group(2))).strip()
    if txt and ('贷款' in txt or '提取' in txt or '缴存' in txt or '办法' in txt or '规定' in txt):
        print(txt,'|',href)
"",
  "description": "Extract loan policy document links"
}

